// src/components/pages/Login.js
import React from "react";
import { useNavigate } from "react-router-dom";

const Login = () => {
  const navigate = useNavigate();

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50">
      <div className="bg-white shadow-xl rounded-3xl p-10 w-full max-w-md">
        <h1 className="text-3xl font-bold mb-6 text-black">Login</h1>
        
        {/* Login Form */}
        <form>
          <input
            type="email"
            placeholder="Email"
            className="w-full mb-4 p-3 rounded-xl border border-gray-300"
          />
          <input
            type="password"
            placeholder="Password"
            className="w-full mb-4 p-3 rounded-xl border border-gray-300"
          />
          <button
            type="submit"
            className="w-full py-3 bg-black text-white rounded-xl font-semibold hover:bg-gray-900 transition"
          >
            Login
          </button>
        </form>

        {/* Change "Sign In" link to "Register" */}
        <p className="mt-6 text-center text-gray-600">
          Don't have an account?{" "}
          <span
            className="text-indigo-600 font-semibold cursor-pointer hover:underline"
            onClick={() => navigate("/signup")}
          >
            Register
          </span>
        </p>
      </div>
    </div>
  );
};

export default Login;
